CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,neighborhood TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',dob TEXT NOT NULL,email_verified INTEGER NOT NULL DEFAULT 0,identity_level INTEGER NOT NULL DEFAULT 0,suspended INTEGER NOT NULL DEFAULT 0,is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE legal_documents(hash TEXT PRIMARY KEY,version TEXT NOT NULL,content TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE consents(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),document_hash TEXT NOT NULL REFERENCES legal_documents(hash),version TEXT NOT NULL,ip_hash TEXT NOT NULL,agent_hash TEXT NOT NULL,accepted_at INTEGER NOT NULL,UNIQUE(user_id,document_hash));
CREATE TABLE action_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),purpose TEXT NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE TABLE seller_accounts(user_id TEXT PRIMARY KEY REFERENCES users(id),mp_user_id TEXT NOT NULL UNIQUE,encrypted_tokens TEXT NOT NULL,expires_at INTEGER NOT NULL,status TEXT NOT NULL,mode TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE oauth_states(state_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),session_hash TEXT NOT NULL,encrypted_verifier TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE offers(id TEXT PRIMARY KEY,provider_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,modality TEXT NOT NULL CHECK(modality IN ('REMOTE','IN_PERSON')),neighborhood TEXT NOT NULL,price_ars INTEGER NOT NULL CHECK(price_ars IN (1000,2500,5000)),blocks INTEGER NOT NULL CHECK(blocks BETWEEN 1 AND 32),availability TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE needs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,neighborhood TEXT NOT NULL,max_price_ars INTEGER NOT NULL CHECK(max_price_ars IN (1000,2500,5000)),blocks INTEGER NOT NULL CHECK(blocks BETWEEN 1 AND 32),active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE favorites(user_id TEXT NOT NULL REFERENCES users(id),offer_id TEXT NOT NULL REFERENCES offers(id),PRIMARY KEY(user_id,offer_id));
CREATE TABLE blocks(user_id TEXT NOT NULL REFERENCES users(id),target_id TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(user_id,target_id),CHECK(user_id<>target_id));
CREATE TABLE bookings(id TEXT PRIMARY KEY,offer_id TEXT NOT NULL REFERENCES offers(id),buyer_id TEXT NOT NULL REFERENCES users(id),seller_id TEXT NOT NULL REFERENCES users(id),need_id TEXT REFERENCES needs(id),parent_id TEXT REFERENCES bookings(id),kind TEXT NOT NULL DEFAULT 'SERVICE',title TEXT NOT NULL,category TEXT NOT NULL,modality TEXT NOT NULL,neighborhood TEXT NOT NULL,price_ars INTEGER NOT NULL CHECK(price_ars IN (1000,2500,5000)),blocks INTEGER NOT NULL CHECK(blocks BETWEEN 1 AND 32),gross_cents INTEGER NOT NULL,commission_cents INTEGER NOT NULL,terms_hash TEXT NOT NULL REFERENCES legal_documents(hash),scheduled_at INTEGER NOT NULL,end_at INTEGER NOT NULL,status TEXT NOT NULL,payment_status TEXT NOT NULL DEFAULT 'UNPAID',payment_deadline INTEGER,primary_payment_id TEXT,notes TEXT NOT NULL DEFAULT '',cancel_reason TEXT,started_at INTEGER,completed_at INTEGER,confirmed_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,CHECK(buyer_id<>seller_id),CHECK(gross_cents=price_ars*blocks*100),CHECK(commission_cents=gross_cents/20));
CREATE INDEX booking_participants ON bookings(seller_id,buyer_id,status,scheduled_at,end_at);
CREATE TABLE attempts(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL UNIQUE REFERENCES bookings(id),external_ref TEXT NOT NULL UNIQUE,mp_seller_id TEXT NOT NULL,status TEXT NOT NULL,preference_id TEXT,checkout_url TEXT,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,next_reconcile INTEGER NOT NULL DEFAULT 0);
CREATE TABLE payments(id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES attempts(id),booking_id TEXT NOT NULL REFERENCES bookings(id),status TEXT NOT NULL,status_detail TEXT NOT NULL,amount_cents INTEGER NOT NULL,refunded_cents INTEGER NOT NULL DEFAULT 0,commission_reported_cents INTEGER,processor_fee_cents INTEGER,net_reported_cents INTEGER,release_status TEXT NOT NULL,release_date TEXT,provider_updated_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE ledger_entries(id TEXT PRIMARY KEY,event_key TEXT NOT NULL UNIQUE,booking_id TEXT NOT NULL REFERENCES bookings(id),payment_id TEXT NOT NULL REFERENCES payments(id),kind TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE ledger_postings(id INTEGER PRIMARY KEY,entry_id TEXT NOT NULL REFERENCES ledger_entries(id),account TEXT NOT NULL,cents INTEGER NOT NULL);
CREATE TABLE refunds(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id),payment_id TEXT NOT NULL REFERENCES payments(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),reason TEXT NOT NULL,actor TEXT NOT NULL,status TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,mp_refund_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id),sender_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE reviews(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id),author_id TEXT NOT NULL REFERENCES users(id),target_id TEXT NOT NULL REFERENCES users(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(booking_id,author_id));
CREATE TABLE reports(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),booking_id TEXT REFERENCES bookings(id),subject_id TEXT,type TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',resolution TEXT,created_at INTEGER NOT NULL);
CREATE TABLE audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,subject TEXT NOT NULL,details TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE jobs(id TEXT PRIMARY KEY,dedupe_key TEXT UNIQUE,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,available_at INTEGER NOT NULL,lease_until INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at INTEGER NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE request_keys(key TEXT PRIMARY KEY,user_id TEXT NOT NULL,payload_hash TEXT NOT NULL,result_id TEXT NOT NULL);
CREATE TABLE mock_payments(id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TRIGGER immutable_entries_update BEFORE UPDATE ON ledger_entries BEGIN SELECT RAISE(ABORT,'ledger append only');END;
CREATE TRIGGER immutable_entries_delete BEFORE DELETE ON ledger_entries BEGIN SELECT RAISE(ABORT,'ledger append only');END;
CREATE TRIGGER immutable_postings_update BEFORE UPDATE ON ledger_postings BEGIN SELECT RAISE(ABORT,'ledger append only');END;
CREATE TRIGGER immutable_postings_delete BEFORE DELETE ON ledger_postings BEGIN SELECT RAISE(ABORT,'ledger append only');END;
CREATE TRIGGER immutable_audit_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'audit append only');END;
CREATE TRIGGER immutable_audit_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'audit append only');END;
CREATE TRIGGER immutable_consent_update BEFORE UPDATE ON consents BEGIN SELECT RAISE(ABORT,'consent append only');END;
CREATE TRIGGER immutable_consent_delete BEFORE DELETE ON consents BEGIN SELECT RAISE(ABORT,'consent append only');END;
CREATE TRIGGER immutable_legal_update BEFORE UPDATE ON legal_documents BEGIN SELECT RAISE(ABORT,'legal append only');END;
CREATE TRIGGER immutable_legal_delete BEFORE DELETE ON legal_documents BEGIN SELECT RAISE(ABORT,'legal append only');END;
CREATE TRIGGER immutable_booking_quote BEFORE UPDATE OF offer_id,buyer_id,seller_id,price_ars,blocks,gross_cents,commission_cents,terms_hash,scheduled_at,end_at ON bookings BEGIN SELECT RAISE(ABORT,'immutable monetary agreement');END;
PRAGMA user_version=1;
